import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { randomUUID } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { mkdir } from 'node:fs/promises';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = resolve(process.env.DB_PATH || resolve(root, 'data/workboard.sqlite'));
await mkdir(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  archived INTEGER NOT NULL DEFAULT 0
)`);
try { db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High'))
)`);
try { db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High'))"); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
const insertProject = db.prepare('INSERT INTO projects (id, name, created_at) VALUES (?, ?, ?)');
const insertTask = db.prepare('INSERT INTO tasks (id, project_id, title, completed, created_at) VALUES (?, ?, ?, 0, ?)');
const listTasks = db.prepare('SELECT id, project_id AS projectId, title, completed, priority FROM tasks WHERE project_id = ? ORDER BY created_at, rowid');
const getTask = db.prepare('SELECT id, project_id AS projectId, title, completed, priority FROM tasks WHERE id = ?');
const setTaskPriority = db.prepare('UPDATE tasks SET priority = ? WHERE id = ?');
const setTaskCompletion = db.prepare('UPDATE tasks SET completed = ? WHERE id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE id = ?');
const listProjects = db.prepare(`SELECT p.id, p.name, p.archived,
  COUNT(t.id) AS totalCount, COALESCE(SUM(t.completed), 0) AS completedCount
  FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
  WHERE p.archived = ? GROUP BY p.id ORDER BY p.created_at, p.rowid`);
const getProject = db.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
const setArchived = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const indexHtml = await readFile(resolve(root, 'public/index.html'));
const appJs = await readFile(resolve(root, 'public/app.js'));
const appCss = await readFile(resolve(root, 'public/style.css'));

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const send = (status, body, type = 'application/json; charset=utf-8') => {
    res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
    res.end(body);
  };
  try {
    if (req.method === 'GET' && url.pathname === '/health') return send(200, JSON.stringify({ status: 'ok' }));
    if (req.method === 'GET' && url.pathname === '/api/projects') {
      const archived = url.searchParams.get('archived') === 'true' ? 1 : 0;
      return send(200, JSON.stringify(listProjects.all(archived)));
    }
    const archiveMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/archive$/);
    if (req.method === 'PATCH' && archiveMatch) {
      const project = getProject.get(archiveMatch[1]);
      if (!project) return send(404, JSON.stringify({ error: 'Project not found' }));
      let raw = '';
      for await (const chunk of req) raw += chunk;
      let payload;
      try { payload = JSON.parse(raw); } catch { return send(400, JSON.stringify({ error: 'Invalid JSON' })); }
      if (typeof payload?.archived !== 'boolean') return send(400, JSON.stringify({ error: 'Invalid archive state' }));
      setArchived.run(payload.archived ? 1 : 0, project.id);
      return send(200, JSON.stringify({ ...project, archived: payload.archived ? 1 : 0 }));
    }
    if (req.method === 'POST' && url.pathname === '/api/projects') {
      let raw = '';
      for await (const chunk of req) raw += chunk;
      let payload;
      try { payload = JSON.parse(raw); } catch { return send(400, JSON.stringify({ error: 'Invalid JSON' })); }
      const name = typeof payload?.name === 'string' ? payload.name.trim() : '';
      if (!name) return send(400, JSON.stringify({ error: 'Project name is required' }));
      const id = randomUUID();
      insertProject.run(id, name, Date.now());
      return send(201, JSON.stringify({ id, name }));
    }
    const renameMatch = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
    if (req.method === 'PATCH' && renameMatch) {
      const project = getProject.get(renameMatch[1]);
      if (!project) return send(404, JSON.stringify({ error: 'Project not found' }));
      if (project.archived) return send(409, JSON.stringify({ error: 'Archived project cannot be changed' }));
      let raw = '';
      for await (const chunk of req) raw += chunk;
      let payload;
      try { payload = JSON.parse(raw); } catch { return send(400, JSON.stringify({ error: 'Invalid JSON' })); }
      const name = typeof payload?.name === 'string' ? payload.name.trim() : '';
      if (!name) return send(400, JSON.stringify({ error: 'Project name is required' }));
      renameProject.run(name, project.id);
      return send(200, JSON.stringify({ ...project, name }));
    }
    const tasksMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks$/);
    if (tasksMatch && (req.method === 'GET' || req.method === 'POST')) {
      const project = getProject.get(tasksMatch[1]);
      if (!project) return send(404, JSON.stringify({ error: 'Project not found' }));
      if (req.method === 'GET') return send(200, JSON.stringify(listTasks.all(tasksMatch[1])));
      if (project.archived) return send(409, JSON.stringify({ error: 'Archived project cannot be changed' }));
      let raw = '';
      for await (const chunk of req) raw += chunk;
      let payload;
      try { payload = JSON.parse(raw); } catch { return send(400, JSON.stringify({ error: 'Invalid JSON' })); }
      const title = typeof payload?.title === 'string' ? payload.title.trim() : '';
      if (!title) return send(400, JSON.stringify({ error: 'Task title is required' }));
      const task = { id: randomUUID(), projectId: tasksMatch[1], title, completed: 0 };
      insertTask.run(task.id, task.projectId, task.title, Date.now());
      return send(201, JSON.stringify(task));
    }
    const taskMatch = url.pathname.match(/^\/api\/tasks\/([^/]+)$/);
    if (req.method === 'PATCH' && taskMatch) {
      let raw = '';
      for await (const chunk of req) raw += chunk;
      let payload;
      try { payload = JSON.parse(raw); } catch { return send(400, JSON.stringify({ error: 'Invalid JSON' })); }
      const task = getTask.get(taskMatch[1]);
      if (!task) return send(404, JSON.stringify({ error: 'Task not found' }));
      if (getProject.get(task.projectId).archived) return send(409, JSON.stringify({ error: 'Archived project cannot be changed' }));
      if (typeof payload?.completed === 'boolean') {
        setTaskCompletion.run(payload.completed ? 1 : 0, task.id);
        return send(200, JSON.stringify({ ...task, completed: payload.completed ? 1 : 0 }));
      }
      if (['Low', 'Normal', 'High'].includes(payload?.priority)) {
        setTaskPriority.run(payload.priority, task.id);
        return send(200, JSON.stringify({ ...task, priority: payload.priority }));
      }
      const title = typeof payload?.title === 'string' ? payload.title.trim() : '';
      if (!title) return send(400, JSON.stringify({ error: 'Task title is required' }));
      renameTask.run(title, task.id);
      return send(200, JSON.stringify({ ...task, title }));
    }
    const projectMatch = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
    if (req.method === 'GET' && projectMatch) {
      const project = getProject.get(projectMatch[1]);
      return project ? send(200, JSON.stringify(project)) : send(404, JSON.stringify({ error: 'Project not found' }));
    }
    if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/[^/]+\/?$/.test(url.pathname))) return send(200, indexHtml, 'text/html; charset=utf-8');
    if (req.method === 'GET' && url.pathname === '/app.js') return send(200, appJs, 'text/javascript; charset=utf-8');
    if (req.method === 'GET' && url.pathname === '/style.css') return send(200, appCss, 'text/css; charset=utf-8');
    return send(404, JSON.stringify({ error: 'Not found' }));
  } catch (error) {
    console.error(error);
    return send(500, JSON.stringify({ error: 'Internal server error' }));
  }
});

const port = Number.parseInt(process.env.PORT || '8080', 10);
server.listen(port, '0.0.0.0', () => console.log(`Workboard listening on ${port}`));

const app = document.querySelector('#app');

async function request(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Request failed');
  return body;
}

function element(tag, attributes = {}, text = '') {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
  if (text) node.textContent = text;
  return node;
}

async function render() {
  app.replaceChildren();
  const match = window.location.pathname.match(/^\/projects\/([^/]+)\/?$/);
  if (match) {
    let project;
    try { project = await request(`/api/projects/${encodeURIComponent(match[1])}`); } catch { project = null; }
    const back = element('button', { type: 'button' }, 'Projects');
    back.addEventListener('click', () => { history.pushState({}, '', '/'); render(); });
    app.append(back);
    if (!project) { app.append(element('p', { role: 'alert' }, 'Project not found')); return; }
    app.append(element('h1', {}, project.name));
    if (project.archived) app.append(element('p', {}, 'Archived project'));
    const renameForm = element('form');
    const renameLabel = element('label', { for: 'new-project-name' }, 'New project name');
    const renameInput = element('input', { id: 'new-project-name', name: 'name', type: 'text' });
    const renameButton = element('button', { type: 'submit' }, 'Rename project');
    const renameAlert = element('p', { role: 'alert', hidden: '' });
    if (project.archived) { renameInput.disabled = true; renameButton.disabled = true; }
    renameForm.append(renameLabel, renameInput, renameButton, renameAlert);
    renameForm.addEventListener('submit', async event => {
      event.preventDefault();
      const name = renameInput.value.trim();
      if (!name) { renameAlert.textContent = 'Project name is required'; renameAlert.hidden = false; renameInput.focus(); return; }
      try {
        await request(`/api/projects/${encodeURIComponent(match[1])}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
        render();
      } catch (error) { renameAlert.textContent = error.message; renameAlert.hidden = false; }
    });
    app.append(renameForm);
    const form = element('form');
    const label = element('label', { for: 'task-title' }, 'Task title');
    const input = element('input', { id: 'task-title', name: 'title', type: 'text' });
    const submit = element('button', { type: 'submit' }, 'Create task');
    const alert = element('p', { role: 'alert', hidden: '' });
    if (project.archived) { input.disabled = true; submit.disabled = true; }
    form.append(label, input, submit, alert);
    const filterLabel = element('label', { for: 'task-filter' }, 'Task filter');
    const filter = element('select', { id: 'task-filter' });
    for (const value of ['All', 'Open', 'Completed']) filter.append(element('option', { value }, value));
    const priorityFilterLabel = element('label', { for: 'priority-filter' }, 'Priority filter');
    const priorityFilter = element('select', { id: 'priority-filter' });
    for (const value of ['All', 'Low', 'Normal', 'High']) priorityFilter.append(element('option', { value }, value));
    const tasks = element('section', { 'aria-label': 'Tasks' });
    app.append(form, filterLabel, filter, priorityFilterLabel, priorityFilter, tasks);
    const refresh = async () => {
      const items = await request(`/api/projects/${encodeURIComponent(match[1])}/tasks`);
      tasks.replaceChildren();
      for (const task of items) {
        if ((filter.value === 'Open' && task.completed) || (filter.value === 'Completed' && !task.completed)) continue;
        if (priorityFilter.value !== 'All' && task.priority !== priorityFilter.value) continue;
        const row = element('div', { 'data-testid': 'task-row', class: 'project-row' });
        row.append(element('span', {}, task.title));
        const renameInput = element('input', { type: 'text', 'aria-label': 'New task title', value: task.title });
        const renameButton = element('button', { type: 'button' }, 'Rename task');
        const renameAlert = element('span', { role: 'alert', hidden: '' });
        renameInput.disabled = Boolean(project.archived);
        renameButton.disabled = Boolean(project.archived);
        renameButton.addEventListener('click', async () => {
          const title = renameInput.value.trim();
          if (!title) { renameAlert.textContent = 'Task title is required'; renameAlert.hidden = false; renameInput.focus(); return; }
          try {
            await request(`/api/tasks/${encodeURIComponent(task.id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
            await refresh();
          } catch (error) { renameAlert.textContent = error.message; renameAlert.hidden = false; }
        });
        row.append(renameInput, renameButton, renameAlert);
        const priority = element('select', { 'aria-label': 'Task priority' });
        for (const value of ['Low', 'Normal', 'High']) priority.append(element('option', { value }, value));
        priority.value = task.priority || 'Normal';
        priority.disabled = Boolean(project.archived);
        priority.addEventListener('change', async () => {
          try {
            await request(`/api/tasks/${encodeURIComponent(task.id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ priority: priority.value }) });
            await refresh();
          } catch (error) { priority.value = task.priority || 'Normal'; }
        });
        row.append(priority);
        const checkbox = element('input', { type: 'checkbox', 'aria-label': `Complete ${task.title}` });
        checkbox.checked = Boolean(task.completed);
        checkbox.disabled = Boolean(project.archived);
        checkbox.addEventListener('change', async () => {
          await request(`/api/tasks/${encodeURIComponent(task.id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
          await refresh();
        });
        row.append(checkbox); tasks.append(row);
      }
    };
    filter.addEventListener('change', refresh);
    priorityFilter.addEventListener('change', refresh);
    form.addEventListener('submit', async event => {
      event.preventDefault();
      const title = input.value.trim();
      if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; input.focus(); return; }
      try {
        await request(`/api/projects/${encodeURIComponent(match[1])}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
        input.value = ''; alert.hidden = true; await refresh();
      } catch (error) { alert.textContent = error.message; alert.hidden = false; }
    });
    await refresh(); return;
  }
  app.append(element('h1', {}, 'Workboard'));
  const form = element('form');
  const label = element('label', { for: 'project-name' }, 'Project name');
  const input = element('input', { id: 'project-name', name: 'name', type: 'text' });
  const submit = element('button', { type: 'submit' }, 'Create project');
  const alert = element('p', { role: 'alert', hidden: '' });
  form.append(label, input, submit, alert);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) { alert.textContent = 'Project name is required'; alert.hidden = false; input.focus(); return; }
    try {
      await request('/api/projects', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
      input.value = ''; alert.hidden = true; await renderProjects();
    } catch (error) { alert.textContent = error.message; alert.hidden = false; }
  });
  app.append(form);
  const labelFilter = element('label', { for: 'project-filter' }, 'Project filter');
  const filter = element('select', { id: 'project-filter' });
  for (const value of ['Active', 'Archived']) filter.append(element('option', { value }, value));
  const list = element('section', { 'aria-label': 'Projects' });
  app.append(labelFilter, filter, list);
  const renderProjects = async () => {
    const projects = await request(`/api/projects?archived=${filter.value === 'Archived'}`);
    list.replaceChildren();
    for (const project of projects) {
      const row = element('div', { 'data-testid': 'project-row', class: 'project-row' });
      row.append(element('span', {}, project.name));
      row.append(element('span', { 'data-testid': 'project-summary' }, `${project.completedCount}/${project.totalCount} completed`));
      const open = element('button', { type: 'button' }, 'Open project');
      open.addEventListener('click', () => { history.pushState({}, '', `/projects/${encodeURIComponent(project.id)}`); render(); });
      const action = element('button', { type: 'button' }, project.archived ? 'Restore project' : 'Archive project');
      action.addEventListener('click', async () => {
        await request(`/api/projects/${encodeURIComponent(project.id)}/archive`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived: !project.archived }) });
        await renderProjects();
      });
      row.append(open, action); list.append(row);
    }
  };
  filter.addEventListener('change', renderProjects);
  await renderProjects();
}

window.addEventListener('popstate', render);
render().catch(error => app.replaceChildren(element('p', { role: 'alert' }, error.message)));

